// SEGURIDAD: sin default de ICP pack.
const incoming = $input.first()?.json ?? {};
const icpPackId = incoming.icp_pack_id || null;
const icpPackSlug = incoming.icp_pack_slug || null;
if (!icpPackId && !icpPackSlug) throw new Error('SEGURIDAD: icp_pack_id o icp_pack_slug es obligatorio (sin valor por defecto). Abortando.');
const filter = icpPackId ? `id=eq.${icpPackId}` : `slug=eq.${icpPackSlug}`;
return [{json:{ limit: incoming.limit, account_ids: incoming.account_ids, icp_pack_url: `https://uwquwjmiofixzugttals.supabase.co/rest/v1/icp_packs?${filter}&select=id,slug,status,qualification&limit=1` }}];

const res = $input.first().json ?? {};
const status = Number(res.statusCode ?? 0);
const body = res.body ?? res;
const row = Array.isArray(body) ? body[0] : body;
if (status < 200 || status >= 300 || !row || !row.id) throw new Error(`ICP Pack no encontrado (HTTP ${status || 'unknown'}).`);
if (row.status !== 'active') throw new Error(`ICP Pack '${row.slug}' esta en estado '${row.status}', no 'active'.`);
const q = row.qualification || {};
if (!q.factor_weights || !q.thresholds) throw new Error(`ICP Pack '${row.slug}' no tiene qualification.factor_weights/thresholds configurados.`);
return [{ json: { icp_pack_id: row.id, icp_pack_slug: row.slug, qualification: q } }];

const EXPECTED_ICP_PACK_ID = 'f412a742-7c7f-4cc0-9e2a-20c39d6fcd46';
const EXPECTED_ICP_PACK_SLUG = 'atacama-labs-test';
const row = $json;
if (row.icp_pack_id !== EXPECTED_ICP_PACK_ID || row.icp_pack_slug !== EXPECTED_ICP_PACK_SLUG) {
  throw new Error(`SEGURIDAD: ICP pack resuelto (${row.icp_pack_slug} / ${row.icp_pack_id}) NO coincide con el esperado (${EXPECTED_ICP_PACK_SLUG} / ${EXPECTED_ICP_PACK_ID}). Abortando antes de leer o escribir nada.`);
}
return [{ json: { ...row, EXPECTED_ICP_PACK_ID } }];

const incoming = $('Init ICP Config').first().json;
const icp = $('Assert Expected Pack').first().json;
const EXPECTED_ICP_PACK_ID = 'f412a742-7c7f-4cc0-9e2a-20c39d6fcd46';
const q = icp.qualification;
const CONFIG = {
  supabase_url: 'https://uwquwjmiofixzugttals.supabase.co',
  qualification_version: 'atacama-03-qualification-test-2026-09-15',
  icp_pack_id: EXPECTED_ICP_PACK_ID,
  factor_weights: q.factor_weights,
  thresholds: q.thresholds,
  evidence_age_days: Number(q.evidence_age_days || 90),
  urgency_age_days: Number(q.urgency_age_days || 30),
  human_review_required: q.human_review_required !== false,
  default_limit: 25,
  max_limit: 25,
};
let accountIds = incoming.account_ids ?? [];
if (typeof accountIds === 'string') { try { accountIds = JSON.parse(accountIds); } catch { accountIds = accountIds.split(',').map(s=>s.trim()).filter(Boolean); } }
if (!Array.isArray(accountIds)) accountIds = [];
accountIds = [...new Set(accountIds.map(String).filter(Boolean))].slice(0, CONFIG.max_limit);
const requestedLimit = Number(incoming.limit ?? CONFIG.default_limit);
const limit = Number.isFinite(requestedLimit) ? Math.max(1, Math.min(CONFIG.max_limit, Math.trunc(requestedLimit))) : CONFIG.default_limit;
const select = 'id,icp_pack_id,name,website,region,commune,city,research_status';
const filters = ['research_status=eq.complete', `icp_pack_id=eq.${EXPECTED_ICP_PACK_ID}`, `select=${select}`, 'order=updated_at.asc', `limit=${limit}`];
if (accountIds.length) filters.push(`id=in.(${accountIds.join(',')})`);
return [{ json: { ...CONFIG, request: { limit, account_ids: accountIds }, eligible_accounts_url: `${CONFIG.supabase_url}/rest/v1/accounts?${filters.join('&')}` } }];

const res = $input.first().json ?? {};
const status = Number(res.statusCode ?? 0);
const body = res.body ?? res;
if (status < 200 || status >= 300) throw new Error(`Supabase eligible accounts read failed: HTTP ${status || 'unknown'}`);
const rows = Array.isArray(body) ? body : [];
if (!rows.length) return [{json:{_no_work:true, reason:'No accounts with research_status=complete matched this run'}}];
return [{json:{_no_work:false, eligible_accounts:rows}}];

let items=[]; try{items=$items('Build Iteration Result').map(x=>x.json.iteration_result).filter(Boolean);}catch{}
const count=k=>items.filter(x=>x.classification===k).length;
return [{json:{ workflow:'Atacama Labs - 03 Qualification (test)', revision: $('Init Configuration').first().json.qualification_version, processed:items.length, hot:count('hot'), warm:count('warm'), cold:count('cold'), results: items }}];

const EXPECTED_ICP_PACK_ID = 'f412a742-7c7f-4cc0-9e2a-20c39d6fcd46';
const item = $json;
if (item.icp_pack_id !== EXPECTED_ICP_PACK_ID) throw new Error(`SEGURIDAD: cuenta ${item.id} tiene icp_pack_id (${item.icp_pack_id}) distinto del esperado (${EXPECTED_ICP_PACK_ID}). Abortando antes de calificarla.`);
return { json: item };

// Implementa contracts/PROSPECTING.md + contracts/prospecting-policy.json EXACTAMENTE.
// Nivel 0/1/2 por factor: 0 sin evidencia, 1 senal indirecta, 2 evidencia concreta.
// Puntos = peso * nivel/2. Score suma 0-100, medios puntos permitidos.
const account = $('Assert Expected Pack (before fetch)').item.json;
const cfg = $('Init Configuration').first().json;
const weights = cfg.factor_weights; // {pain,budgetProxy,volume,automation,access,urgency,fit}
const thresholds = cfg.thresholds; // {A,B}
const evidenceAgeDays = cfg.evidence_age_days;
const urgencyAgeDays = cfg.urgency_age_days;

const researchRes = $('Fetch Research').item.json ?? {};
const researchStatus = Number(researchRes.statusCode ?? 0);
const researchRows = researchStatus >= 200 && researchStatus < 300 && Array.isArray(researchRes.body) ? researchRes.body : [];

const contactsRes = $('Fetch Contacts').item.json ?? {};
const contactsStatus = Number(contactsRes.statusCode ?? 0);
const contactRows = contactsStatus >= 200 && contactsStatus < 300 && Array.isArray(contactsRes.body) ? contactsRes.body : [];

const FACTOR_KEYS = { pain: 'pain', budgetProxy: 'budget_proxy', volume: 'volume', automation: 'automation', access: 'access', urgency: 'urgency', fit: 'fit' };
const now = Date.now();
const ageDays = (dateStr) => { if (!dateStr) return Infinity; const t = new Date(dateStr).getTime(); if (!Number.isFinite(t)) return Infinity; return (now - t) / (1000*60*60*24); };

const factors = {};
const uncertainty = [];
let rawScore = 0;

for (const [weightKey, factorType] of Object.entries(FACTOR_KEYS)) {
  const rows = researchRows.filter(r => r.research_type === 'factor:' + factorType);
  // Best evidence: highest level first, then most recent verified_at/source_date.
  let best = null;
  for (const r of rows) {
    const level = Number(r?.raw_metadata?.level);
    if (![0, 1, 2].includes(level)) continue;
    const evAge = ageDays(r.source_date || r.verified_at);
    if (!best || level > best.level || (level === best.level && evAge < best.ageDays)) {
      best = { level, ageDays: evAge, finding: r.finding, source_url: r.source_url, source_date: r.source_date, certainty: r?.raw_metadata?.certainty || 'inferred' };
    }
  }
  const weight = Number(weights[weightKey] || 0);
  let level = best ? best.level : 0;
  let stale = false;
  // Vigencia: evidencia de urgencia >30 dias se trata como no vigente (no cuenta el nivel
  // encontrado, per contracts/PROSPECTING.md "revisar si >30 dias"); otros factores usan
  // evidence_age_days (90) como limite de vigencia general antes de outreach, no para el
  // score en si -- se registra como incertidumbre, no se fuerza a 0, salvo urgencia.
  if (best) {
    if (factorType === 'urgency' && best.ageDays > urgencyAgeDays) { stale = true; level = 0; uncertainty.push('urgency_stale'); }
    else if (best.ageDays > evidenceAgeDays) { uncertainty.push(factorType + '_evidence_aged'); }
  }
  const points = weight * (level / 2);
  rawScore += points;
  factors[weightKey] = { level, weight, points, evidence: best ? { finding: best.finding, source_url: best.source_url, source_date: best.source_date, certainty: best.certainty, stale } : null, unknown: !best };
}
rawScore = Math.round(rawScore * 2) / 2; // medios puntos permitidos

// Contacto verificable: al menos un contacto con email o telefono.
const bestContact = contactRows.find(c => c.email || c.phone) || contactRows[0] || null;
const contactVerified = Boolean(bestContact && (bestContact.email || bestContact.phone));

// Empresa verificada: la propia cuenta existe con nombre + (website o direccion) -- ya
// esta en accounts por Discovery, se toma como verificada si tiene nombre y algun canal.
const companyVerified = Boolean(account.name && (account.website || account.city));

const painVerified = factors.pain.level >= 1;
const evidenceVigente = !uncertainty.includes('urgency_stale');

return [{
  json: {
    account,
    factors,
    raw_score: rawScore,
    final_score: rawScore, // sin penalizaciones de incumbencia -- no aplica a Atacama
    contact_verified: contactVerified,
    primary_contact: bestContact,
    company_verified: companyVerified,
    pain_verified: painVerified,
    evidence_vigente: evidenceVigente,
    uncertainty_codes: uncertainty,
    thresholds,
  },
}];

// Gates per contracts/PROSPECTING.md:
// A >= 80 AND empresa verificada AND dolor nivel>=1 AND contacto verificable AND evidencia vigente.
// Si score>=80 pero falla un gate, degrada a B con motivo. B >= 60 si no cumple gate A.
// C < 60 o research incompleto.
const s = $json;
const { raw_score, final_score, contact_verified, company_verified, pain_verified, evidence_vigente, thresholds } = s;
let classification;
let gate_reason = null;

const gateAOk = final_score >= thresholds.A && company_verified && pain_verified && contact_verified && evidence_vigente;

if (final_score >= thresholds.A) {
  if (gateAOk) { classification = 'A'; }
  else {
    const failed = [];
    if (!company_verified) failed.push('empresa_no_verificada');
    if (!pain_verified) failed.push('dolor_no_verificado');
    if (!contact_verified) failed.push('contacto_no_verificable');
    if (!evidence_vigente) failed.push('evidencia_no_vigente');
    classification = final_score >= thresholds.B ? 'B' : 'C';
    gate_reason = 'score>=A pero gate A fallo: ' + failed.join(',');
  }
} else if (final_score >= thresholds.B) {
  classification = 'B';
} else {
  classification = 'C';
}

// Mapeo al enum existente de prospects.classification (hot/warm/cold) -- A=hot, B=warm, C=cold.
const dbClassification = classification === 'A' ? 'hot' : classification === 'B' ? 'warm' : 'cold';

return [{ json: { ...s, classification_letter: classification, classification: dbClassification, gate_reason } }];

const EXPECTED_ICP_PACK_ID = 'f412a742-7c7f-4cc0-9e2a-20c39d6fcd46';
const cfgId = $('Init Configuration').first().json.icp_pack_id;
if (cfgId !== EXPECTED_ICP_PACK_ID) throw new Error(`SEGURIDAD: icp_pack_id (${cfgId}) no coincide con el esperado (${EXPECTED_ICP_PACK_ID}) justo antes de escribir en prospects. Abortando.`);
return $input.all();

const s = $json;
const cfg = $('Init Configuration').first().json;
const EXPECTED_ICP_PACK_ID = 'f412a742-7c7f-4cc0-9e2a-20c39d6fcd46';
const factorSummary = Object.entries(s.factors).map(([k, f]) => `${k}=${f.level}(${f.points}pt)${f.unknown ? '?' : ''}`).join(', ');
const reason = `classification=${s.classification_letter}; raw=${s.raw_score}; final=${s.final_score}; factors: ${factorSummary}${s.gate_reason ? '; ' + s.gate_reason : ''}${s.uncertainty_codes.length ? '; uncertainty=' + s.uncertainty_codes.join('|') : ''}`;
const angle = s.factors.pain.evidence?.finding || s.factors.fit.evidence?.finding || 'Sin angulo comercial especifico detectado todavia.';

const payload = {
  prospect_key: 'account:' + s.account.id,
  icp_pack_id: EXPECTED_ICP_PACK_ID,
  account_id: s.account.id,
  primary_contact_id: s.primary_contact?.id || null,
  classification: s.classification,
  score: Math.round(s.final_score),
  raw_score: Math.round(s.raw_score),
  final_score: Math.round(s.final_score),
  operator_confirmed: false,
  operator_required: false,
  operation_current: s.company_verified === true,
  pain_verified: s.pain_verified,
  contact_verified: s.contact_verified,
  commercial_angle: angle.slice(0, 500),
  qualification_reason: reason.slice(0, 2000),
  status: 'new',
  crm_candidate: s.classification_letter === 'A',
  metadata: {
    human_review_required: cfg.human_review_required,
    factors: s.factors,
    uncertainty_codes: s.uncertainty_codes,
    qualification_version: cfg.qualification_version,
    scored_at: new Date().toISOString(),
  },
};
return [{ json: { ...s, prospect_payload: payload } }];

const state = $('Build Prospect Payload').item.json;
const res = $input.first().json ?? {};
const status = Number(res.statusCode ?? 0);
const body = res.body ?? res;
if (status < 200 || status >= 300 || !Array.isArray(body) || body.length !== 1) {
  const detail = typeof body === 'string' ? body : JSON.stringify(body).slice(0, 800);
  throw new Error(`Prospect upsert rejected for ${state.prospect_payload.prospect_key}: HTTP ${status || 'unknown'} ${detail}`);
}
return [{ json: { ...state, persisted_prospect: body[0] } }];

const s = $json;
return [{ json: { iteration_result: {
  account_id: s.account.id, account_name: s.account.name,
  classification: s.classification_letter, score: s.final_score, crm_candidate: s.prospect_payload.crm_candidate,
  prospect_id: s.persisted_prospect?.id || null, gate_reason: s.gate_reason,
} } }];
